package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;
import com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow;
import java.io.Reader;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        boolean exactContains;
        int exactIndex;
        boolean exactManualContains = false;
        int exactManualIndex = -1;
        int exactCapacityBefore;
        int exactCapacityAfter;
        int exactLengthBefore;
        int exactLengthAfter;
        try {
            StrBuilder sb = new StrBuilder("onetwothree");
            sb.deleteFirst("three");

            exactCapacityBefore = sb.capacity();
            exactLengthBefore = sb.length();
            exactContains = sb.contains('h');
            exactCapacityAfter = sb.capacity();
            exactLengthAfter = sb.length();
            exactIndex = sb.indexOf('h');

            Reader r = sb.asReader();
            int pos = 0;
            int c;
            while ((c = r.read()) != -1) {
                if ((char) c == 'h') {
                    if (!exactManualContains) {
                        exactManualContains = true;
                        exactManualIndex = pos;
                    }
                }
                pos++;
            }
        } catch (Throwable t) {
            return;
        }

        if (exactContains != false) {
            throw new FuzzerSecurityIssueLow("[oracle:lang295-contains] semantic mismatch: after new StrBuilder(\"onetwothree\").deleteFirst(\"three\"), contains('h') expected=false actual=" + exactContains);
        }
        if (exactIndex != -1) {
            throw new FuzzerSecurityIssueLow("[oracle:lang295-indexof] semantic mismatch: after new StrBuilder(\"onetwothree\").deleteFirst(\"three\"), indexOf('h') expected=-1 actual=" + exactIndex);
        }
        if (exactContains != exactManualContains) {
            throw new FuzzerSecurityIssueLow("[oracle:seed-reader-agreement] consistency violation: contains('h')=" + exactContains + " but asReader() exposed contains=" + exactManualContains);
        }
        if (exactIndex != exactManualIndex) {
            throw new FuzzerSecurityIssueLow("[oracle:seed-reader-index] consistency violation: indexOf('h')=" + exactIndex + " but asReader() recomputed index=" + exactManualIndex);
        }
        // contains(char) is documented as a query ("whether the builder contains the character"), so it must not mutate observable state.
        // A throw-deleting or band-aid patch that silently rewrites internal storage would violate this read-only contract.
        if (exactCapacityBefore != exactCapacityAfter || exactLengthBefore != exactLengthAfter) {
            throw new FuzzerSecurityIssueLow("[oracle:contains-readonly-seed] post-condition violation: contains(char) changed state capacity " + exactCapacityBefore + "->" + exactCapacityAfter + " length " + exactLengthBefore + "->" + exactLengthAfter);
        }

        String base = data.consumeAsciiString(data.consumeInt(1, 32));
        if (base.length() == 0) {
            base = "A";
        }

        String del;
        if (data.consumeBoolean()) {
            int start = data.consumeInt(0, base.length() - 1);
            int end = data.consumeInt(start + 1, base.length());
            del = base.substring(start, end);
        } else {
            del = data.consumeAsciiString(data.consumeInt(1, 8));
            if (del.length() == 0) {
                del = "Z";
            }
        }

        char probe = (char) data.consumeInt(0, 127);

        boolean fuzzContains;
        int fuzzIndex;
        boolean manualContains = false;
        int manualIndex = -1;
        int capacityBefore;
        int capacityAfter;
        int lengthBefore;
        int lengthAfter;

        try {
            StrBuilder sb = new StrBuilder(base);
            sb.ensureCapacity(base.length() + 32 + data.consumeInt(0, 32));
            sb.deleteFirst(del);

            capacityBefore = sb.capacity();
            lengthBefore = sb.length();
            fuzzContains = sb.contains(probe);
            capacityAfter = sb.capacity();
            lengthAfter = sb.length();
            fuzzIndex = sb.indexOf(probe);

            Reader r = sb.asReader();
            int pos = 0;
            int c;
            while ((c = r.read()) != -1) {
                if ((char) c == probe) {
                    if (!manualContains) {
                        manualContains = true;
                        manualIndex = pos;
                    }
                }
                pos++;
            }
        } catch (Throwable t) {
            return;
        }

        // contains(char) and indexOf(char) answer the same logical question: a char is contained iff its first index is non-negative.
        if (fuzzContains != (fuzzIndex >= 0)) {
            throw new FuzzerSecurityIssueLow("[oracle:contains-indexof-agree] metamorphic violation: contains=" + fuzzContains + " indexOf=" + fuzzIndex + " probe=" + (int) probe + " base=" + base + " delete=" + del);
        }
        // asReader() exposes the builder's current logical contents only; recomputing containment from that output must match contains(char).
        if (fuzzContains != manualContains) {
            throw new FuzzerSecurityIssueLow("[oracle:reader-contains-agree] consistency violation: contains=" + fuzzContains + " readerContains=" + manualContains + " probe=" + (int) probe + " base=" + base + " delete=" + del);
        }
        // The first position reported by indexOf(char) must equal the first position independently recomputed from asReader().
        if (fuzzIndex != manualIndex) {
            throw new FuzzerSecurityIssueLow("[oracle:reader-index-agree] consistency violation: indexOf=" + fuzzIndex + " readerIndex=" + manualIndex + " probe=" + (int) probe + " base=" + base + " delete=" + del);
        }
        // contains(char) is a read-only query by contract, so observable size/capacity must not change across the call.
        if (capacityBefore != capacityAfter || lengthBefore != lengthAfter) {
            throw new FuzzerSecurityIssueLow("[oracle:contains-readonly-fuzz] post-condition violation: contains(char) changed state capacity " + capacityBefore + "->" + capacityAfter + " length " + lengthBefore + "->" + lengthAfter + " base=" + base + " delete=" + del + " probe=" + (int) probe);
        }
    }
}

package org.apache.commons.lang.text;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static String stripChar(String s, char ch) {
        if (s == null || s.length() == 0) {
            return "";
        }
        StringBuffer out = new StringBuffer(s.length());
        for (int i = 0; i < s.length(); i++) {
            char cur = s.charAt(i);
            if (cur != ch) {
                out.append(cur);
            }
        }
        return out.toString();
    }

    private static String repeat(char ch, int count) {
        StringBuffer out = new StringBuffer(count);
        for (int i = 0; i < count; i++) {
            out.append(ch);
        }
        return out.toString();
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        StrBuilder sb = new StrBuilder("onetwothree");
        sb.deleteFirst("three");

        int capacityBeforeContains = sb.capacity();
        int lengthBeforeContains = sb.length();
        boolean actualContains = sb.contains('h');
        if (actualContains != false) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lang295-contains] semantic mismatch: expected contains('h')=false after deleteFirst(\"three\"), actual=" + actualContains);
        }

        int actualIndex = sb.indexOf('h');
        if (actualIndex != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lang295-indexof] semantic mismatch: expected indexOf('h')=-1 after deleteFirst(\"three\"), actual=" + actualIndex);
        }

        // contains(char) is documented as a pure check ("Checks if the string builder contains the specified char").
        // The documented buffer-changing operations are constructors, setLength, ensureCapacity, and minimizeCapacity.
        // Therefore this query must not change observable builder state such as length or capacity.
        if (sb.length() != lengthBeforeContains) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-length-stable-seed] consistency violation: contains(char) changed length from "
                    + lengthBeforeContains + " to " + sb.length());
        }
        if (sb.capacity() != capacityBeforeContains) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:contains-capacity-stable-seed] consistency violation: contains(char) changed capacity from "
                    + capacityBeforeContains + " to " + sb.capacity());
        }

        String rawPrefix = data.consumeAsciiString(32);
        char needle = (char) ('a' + data.consumeInt(0, 25));
        int suffixLen = data.consumeInt(1, 8);

        String prefix = stripChar(rawPrefix, needle);
        String suffix = repeat(needle, suffixLen);
        StrBuilder fuzzed = new StrBuilder(prefix + suffix);
        fuzzed.deleteFirst(suffix);

        int fuzzLengthBefore = fuzzed.length();
        int fuzzCapacityBefore = fuzzed.capacity();

        try {
            fuzzed.contains(needle);
        } catch (Throwable t) {
            return;
        }

        // Same documented guarantee as above: contains(char) is a check, so it must not mutate
        // length/capacity. This remains a valid oracle even if a band-aid patch merely forces the
        // returned boolean to look correct while leaving shared buffer state inconsistent.
        if (fuzzed.length() != fuzzLengthBefore) {
            throw new RuntimeException(
                "[oracle:contains-length-stable-fuzz] metamorphic violation: contains(char) changed length inputPrefix="
                    + prefix + " suffixLen=" + suffixLen + " before=" + fuzzLengthBefore + " after=" + fuzzed.length());
        }
        if (fuzzed.capacity() != fuzzCapacityBefore) {
            throw new RuntimeException(
                "[oracle:contains-capacity-stable-fuzz] metamorphic violation: contains(char) changed capacity inputPrefix="
                    + prefix + " suffixLen=" + suffixLen + " before=" + fuzzCapacityBefore + " after=" + fuzzed.capacity());
        }
    }
}

// relation: minus_positive_zero_has_no_forced_space
// holds because: The only documented reason for inserting a space here is to prevent misparsing of a negative literal after '-'; for a non-negative zero literal there is no such ambiguity, so compact printing must keep the compact form.
// valid input: Use the adjacent boundary value to the patched predicate: positive zero after a minus operator, i.e. source "x-0".
String js = "x-0";
String out;
try {
  Compiler c = new Compiler();
  com.google.javascript.rhino.Node root = c.parseTestCode(js);
  out = new CodePrinter.Builder(root)
      .setPrettyPrint(false)
      .setLineLengthThreshold(CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD)
      .build();
} catch (Exception e) { return; }
if (!"x-0".equals(out)) {
  throw new RuntimeException("relation minus_positive_zero_has_no_forced_space violated: " + out);
}

