// valid input: Choose small positive integers `left` and `right` in [1,99] so both print in ordinary decimal form, and build a subtraction AST with a positive right operand.
int left = data.consumeInt(1, 99);
int right = data.consumeInt(1, 99);
String out;
try {
  com.google.javascript.rhino.Node expr = new com.google.javascript.rhino.Node(
      com.google.javascript.rhino.Token.SUB,
      com.google.javascript.rhino.Node.newNumber((double) left),
      com.google.javascript.rhino.Node.newNumber((double) right));
  out = new com.google.javascript.jscomp.CodePrinter.Builder(expr)
      .setPrettyPrint(false)
      .setLineLengthThreshold(com.google.javascript.jscomp.CodePrinter.DEFAULT_LINE_LENGTH_THRESHOLD)
      .build();
} catch (Exception e) { return; }
String expected = left + "-" + right;
if (!expected.equals(out)) {
  throw new RuntimeException("relation subtraction_positive_integer_has_no_extra_separator violated: expected " + expected + " but got " + out);
