                break;
            case 1:
                base = java.util.Map.Entry.class;
                break;
            case 2:
                base = int.class;
                break;
            default:
                base = boolean.class;
                break;
        }

        int dims = data.consumeInt(0, 3);
        Class<?> cls = base;
        String lhs;
        String rhs;
        String canonical;

        try {
            for (int i = 0; i < dims; i++) {
                cls = Array.newInstance(cls, 0).getClass();
            }
            canonical = cls.getCanonicalName();
            if (canonical == null) {
                return;
            }

            /*
             * Contract justification:
             * getPackageName(Class) and getPackageCanonicalName(String) are sibling overloads in the same
             * get* family. For a real Class whose canonical name is available, passing that canonical name
             * into the canonical-string overload must agree with the Class overload on the same logical type.
             * This is a directly observable post-condition; a patch that merely avoids the buggy path or
             * silently returns a JVM-internal array encoding will violate this agreement.
             */
            lhs = ClassUtils.getPackageName(cls);
            rhs = ClassUtils.getPackageCanonicalName(canonical);
        } catch (Exception e) {
