            throw new FuzzerSecurityIssueLow("[oracle:pkg-class-canonical-agreement] metamorphic violation: ClassUtils.getPackageName(Class) must agree with ClassUtils.getPackageCanonicalName(String) for canonicalName=" + canonical + " lhs=" + lhs + " rhs=" + rhs);
