                base = String.class;
                break;
            case 1:
                base = java.util.Map.Entry.class;
                break;
            case 2:
                base = int.class;
                break;
            default:
                base = boolean.class;
                break;
        }

        int dims = data.consumeInt(1, 4);
        Class<?> arrayCls = base;
        String actual;
        String baseShort;

        try {
            for (int i = 0; i < dims; i++) {
                arrayCls = Array.newInstance(arrayCls, 0).getClass();
            }

            /*
             * Contract justification:
             * getShortClassName(Class) returns the class name without the package. For arrays, the human-readable
             * form is the component short name followed by one [] per dimension, not the JVM internal encoding.
             * Building the array Class from a chosen base and dimension count makes the expected answer trusted:
             * we choose the component type first, then append exactly dims bracket pairs.
             */
            actual = ClassUtils.getShortClassName(arrayCls);
            baseShort = ClassUtils.getShortClassName(base);
        } catch (Exception e) {
            return;
        }

        String expected = baseShort;
        for (int i = 0; i < dims; i++) {
            expected += "[]";
        }

