// relation: integrate_returns_requested_end_time_without_events
// holds because: The integrator performs ODE integration up to the supplied target time `t`; with no event handlers installed, the built-in end-time checker should make the integration stop at that end time, so `integrate(..., t, ...)` returns that stop time.
// valid input: Choose a small positive dimension 1..4, an initial time `t0`, and a distinct target time `t` in either direction. Build a valid `FirstOrderDifferentialEquations` with zero derivatives so integration is always well-defined and has no singularities. Use positive `minStep < maxStep` and any `nSteps >= 2`.
int dim = data.consumeInt(1, 4);
int nSteps = data.consumeInt(2, 6);
double t0 = data.consumeInt(-20, 20);
double delta = data.consumeInt(1, 20);
double t = data.consumeBoolean() ? t0 + delta : t0 - delta;
double[] y0 = new double[dim];
for (int i = 0; i < dim; ++i) { y0[i] = data.consumeInt(-10, 10); }
double[] y = new double[dim];
org.apache.commons.math.ode.FirstOrderDifferentialEquations eq = new org.apache.commons.math.ode.FirstOrderDifferentialEquations() {
  public int getDimension() { return dim; }
  public void computeDerivatives(double time, double[] state, double[] yDot) {
    for (int i = 0; i < yDot.length; ++i) { yDot[i] = 0.0; }
  }
};
org.apache.commons.math.ode.nonstiff.AdamsMoultonIntegrator integ = new org.apache.commons.math.ode.nonstiff.AdamsMoultonIntegrator(nSteps, 1.0e-6, 1.0, 1.0e-9, 1.0e-9);
double stop;
try {
  stop = integ.integrate(eq, t0, y0, t, y);
} catch (Exception e) { return; }
double tol = 1e-9 * Math.max(1.0, Math.max(Math.abs(stop), Math.abs(t)));
if (Math.abs(stop - t) > tol) throw new RuntimeException("relation integrate_returns_requested_end_time_without_events violated: stop=" + stop + " target=" + t);

