package org.apache.commons.math3.stat.inference;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        MannWhitneyUTest testStatistic = new MannWhitneyUTest();

        // New oracle family, distinct from the listed covered families:
        // Construct a canonical no-ties, fully separated input family around the int-overflow boundary.
        // For all i, x[i] < y[j] for every j. By the Mann-Whitney definition and the library's public API,
        // one sample then has U=0 and the other has U=n1*n2; the public mannWhitneyU method returns the larger U,
        // so the trusted answer is exactly n1*n2 for this constructed family.
        // This uses a known-answer construction, not a guessed expected value.
        int n = data.consumeInt(46340, 46343);
        double[] x = new double[n];
        double[] y = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = i;
            y[i] = i + n + 1.0;
        }

        double u;
        try {
            u = testStatistic.mannWhitneyU(x, y);
        } catch (Throwable t) {
            return;
        }
        double expectedU = ((double) n) * ((double) n);
        if (Double.compare(u, expectedU) != 0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:canonical-separated-u] semantic mismatch: n=" + n
                    + " expectedU=" + expectedU + " actualU=" + u);
        }

        // Mandatory post-condition / metamorphic check:
        // For the same fully separated, no-ties family, increasing n to n+1 strengthens the evidence and keeps Umin=0.
        // In the documented asymptotic p-value computation reachable from mannWhitneyUTest, the resulting z-score
        // moves farther into the tail as n grows, so the two-sided p-value must strictly decrease.
        // A band-aid patch that merely suppresses the known seed symptom but leaves the overflowed n1*n2 path wrong
        // will violate this monotonic relation just past the overflow boundary.
        double[] xNext = new double[n + 1];
        double[] yNext = new double[n + 1];
        for (int i = 0; i < n + 1; i++) {
            xNext[i] = i;
            yNext[i] = i + (n + 1) + 1.0;
        }

        double pN;
        double pNext;
        try {
            pN = testStatistic.mannWhitneyUTest(x, y);
            pNext = testStatistic.mannWhitneyUTest(xNext, yNext);
        } catch (Throwable t) {
            return;
        }
        if (!(pNext < pN)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:overflow-boundary-monotone-p] metamorphic violation: "
                    + "expected p(n+1) < p(n) for fully separated equal-sized samples near overflow boundary, "
                    + "n=" + n + " p(n)=" + pN + " p(n+1)=" + pNext);
        }

        // Lifted oracle from MannWhitneyUTestTest.testBigDataSet:
        // exact reconstructed setup from the test class field `protected MannWhitneyUTest testStatistic = new MannWhitneyUTest();`
        // and exact assertion `Assert.assertTrue(result > 0.1);`
        double[] d1 = new double[1500];
        double[] d2 = new double[1500];
        for (int i = 0; i < 1500; i++) {
            d1[i] = 2.0 * i;
            d2[i] = 2.0 * i + 1.0;
        }

        double result;
        try {
            result = new MannWhitneyUTest().mannWhitneyUTest(d1, d2);
        } catch (Throwable t) {
            return;
        }
        if (!(result > 0.1)) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-big-dataset-threshold] semantic mismatch: expected result > 0.1 but got " + result);
        }
    }
}

