package org.jfree.data.time;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    private static double middle(TimePeriod p) {
        return (((double) p.getStart().getTime()) + ((double) p.getEnd().getTime())) / 2.0;
    }

    public static void fuzzerTestOneInput(com.code_intelligence.jazzer.api.FuzzedDataProvider data) {
        TimePeriodValues lifted = null;
        int actual0 = Integer.MIN_VALUE;
        int actual1 = Integer.MIN_VALUE;
        int actual2 = Integer.MIN_VALUE;
        int actual3 = Integer.MIN_VALUE;
        int actual4 = Integer.MIN_VALUE;
        try {
            lifted = new TimePeriodValues("Test");
            actual0 = lifted.getMaxMiddleIndex();
            lifted.add(new SimpleTimePeriod(100L, 200L), 1.0);
            actual1 = lifted.getMaxMiddleIndex();
            lifted.add(new SimpleTimePeriod(300L, 400L), 2.0);
            actual2 = lifted.getMaxMiddleIndex();
            lifted.add(new SimpleTimePeriod(0L, 50L), 3.0);
            actual3 = lifted.getMaxMiddleIndex();
            lifted.add(new SimpleTimePeriod(150L, 200L), 4.0);
            actual4 = lifted.getMaxMiddleIndex();
        } catch (Throwable t) {
            return;
        }

        if (actual0 != -1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-0] semantic mismatch: expected s.getMaxMiddleIndex() == -1 on new TimePeriodValues(\"Test\"), actual=" + actual0);
        }
        if (actual1 != 0) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-1] semantic mismatch: after s.add(new SimpleTimePeriod(100L, 200L), 1.0), expected getMaxMiddleIndex() == 0, actual=" + actual1);
        }
        if (actual2 != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-2] semantic mismatch: after s.add(new SimpleTimePeriod(300L, 400L), 2.0), expected getMaxMiddleIndex() == 1, actual=" + actual2);
        }
        if (actual3 != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-3] semantic mismatch: after s.add(new SimpleTimePeriod(0L, 50L), 3.0), expected getMaxMiddleIndex() == 1, actual=" + actual3);
        }
        if (actual4 != 1) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-4] semantic mismatch: after s.add(new SimpleTimePeriod(150L, 200L), 4.0), expected getMaxMiddleIndex() == 1, actual=" + actual4);
        }

        TimePeriodValues readonly = null;
        int beforeItemCount = 0;
        int beforeMaxEnd = 0;
        int beforeMaxMiddle = 0;
        int beforeMaxStart = 0;
        int beforeMinEnd = 0;
        int beforeMinMiddle = 0;
        int beforeMinStart = 0;
        int beforeHash = 0;
        int queried = 0;
        int afterItemCount = 0;
        int afterMaxEnd = 0;
        int afterMaxMiddle = 0;
        int afterMaxStart = 0;
        int afterMinEnd = 0;
        int afterMinMiddle = 0;
        int afterMinStart = 0;
        int afterHash = 0;
        try {
            readonly = new TimePeriodValues("ReadOnly");
            readonly.add(new SimpleTimePeriod(10L, 20L), 1.0);
            readonly.add(new SimpleTimePeriod(30L, 40L), 2.0);
            readonly.add(new SimpleTimePeriod(5L, 15L), 3.0);

            beforeItemCount = readonly.getItemCount();
            beforeMaxEnd = readonly.getMaxEndIndex();
            beforeMaxMiddle = readonly.getMaxMiddleIndex();
            beforeMaxStart = readonly.getMaxStartIndex();
            beforeMinEnd = readonly.getMinEndIndex();
            beforeMinMiddle = readonly.getMinMiddleIndex();
            beforeMinStart = readonly.getMinStartIndex();
            beforeHash = readonly.hashCode();

            queried = readonly.getMaxMiddleIndex();

            afterItemCount = readonly.getItemCount();
            afterMaxEnd = readonly.getMaxEndIndex();
            afterMaxMiddle = readonly.getMaxMiddleIndex();
            afterMaxStart = readonly.getMaxStartIndex();
            afterMinEnd = readonly.getMinEndIndex();
            afterMinMiddle = readonly.getMinMiddleIndex();
            afterMinStart = readonly.getMinStartIndex();
            afterHash = readonly.hashCode();
        } catch (Throwable t) {
            return;
        }

        /* Contract justification: getMaxMiddleIndex() is a getter ("Returns the index") and is documented as a read-only query.
           A throw-deleting or bookkeeping-skipping patch that mutates state during this query would violate these observable readers. */
        if (beforeItemCount != afterItemCount
                || beforeMaxEnd != afterMaxEnd
                || beforeMaxMiddle != afterMaxMiddle
                || beforeMaxStart != afterMaxStart
                || beforeMinEnd != afterMinEnd
                || beforeMinMiddle != afterMinMiddle
                || beforeMinStart != afterMinStart
                || beforeHash != afterHash
                || queried != afterMaxMiddle) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:readonly-getter] semantic mismatch: getMaxMiddleIndex() changed observable state"
                    + " before={count=" + beforeItemCount
                    + ",maxEnd=" + beforeMaxEnd
                    + ",maxMiddle=" + beforeMaxMiddle
                    + ",maxStart=" + beforeMaxStart
                    + ",minEnd=" + beforeMinEnd
                    + ",minMiddle=" + beforeMinMiddle
                    + ",minStart=" + beforeMinStart
                    + ",hash=" + beforeHash
                    + "} after={count=" + afterItemCount
                    + ",maxEnd=" + afterMaxEnd
                    + ",maxMiddle=" + afterMaxMiddle
                    + ",maxStart=" + afterMaxStart
                    + ",minEnd=" + afterMinEnd
                    + ",minMiddle=" + afterMinMiddle
                    + ",minStart=" + afterMinStart
                    + ",hash=" + afterHash
                    + "} queried=" + queried);
        }

        TimePeriodValues siblingA = null;
        TimePeriodValues siblingB = null;
        int siblingAMaxMiddle = 0;
        int siblingBMaxMiddle = 0;
        int siblingAMaxEnd = 0;
        int siblingBMaxEnd = 0;
        int siblingACount = 0;
        int siblingBCount = 0;
        try {
            siblingA = new TimePeriodValues("Sibling");
            siblingB = new TimePeriodValues("Sibling");

            long p1s = data.consumeInt(-1000, 1000);
            long p1e = p1s + data.consumeInt(0, 1000);
            long p2s = data.consumeInt(-1000, 1000);
            long p2e = p2s + data.consumeInt(0, 1000);
            long p3s = data.consumeInt(-1000, 1000);
            long p3e = p3s + data.consumeInt(0, 1000);

            int v1 = data.consumeInt(-1000000, 1000000);
            int v2 = data.consumeInt(-1000000, 1000000);
            int v3 = data.consumeInt(-1000000, 1000000);

            siblingA.add(new SimpleTimePeriod(p1s, p1e), (double) v1);
            siblingA.add(new SimpleTimePeriod(p2s, p2e), (double) v2);
            siblingA.add(new SimpleTimePeriod(p3s, p3e), (double) v3);

            siblingB.add(new SimpleTimePeriod(p1s, p1e), new Integer(v1));
            siblingB.add(new SimpleTimePeriod(p2s, p2e), new Integer(v2));
            siblingB.add(new SimpleTimePeriod(p3s, p3e), new Integer(v3));

            siblingAMaxMiddle = siblingA.getMaxMiddleIndex();
            siblingBMaxMiddle = siblingB.getMaxMiddleIndex();
            siblingAMaxEnd = siblingA.getMaxEndIndex();
            siblingBMaxEnd = siblingB.getMaxEndIndex();
            siblingACount = siblingA.getItemCount();
            siblingBCount = siblingB.getItemCount();
        } catch (Throwable t) {
            return;
        }

        /* Contract justification: the add(TimePeriod,double) and add(TimePeriod,Number) overloads are sibling APIs for the same logical add operation.
           On equivalent inputs they must establish the same collection state and therefore the same extrema indices. */
        if (siblingACount != siblingBCount
                || siblingAMaxMiddle != siblingBMaxMiddle
                || siblingAMaxEnd != siblingBMaxEnd) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:add-overload-agreement] semantic mismatch: equivalent add overloads disagreed"
                    + " counts=" + siblingACount + "/" + siblingBCount
                    + " maxMiddle=" + siblingAMaxMiddle + "/" + siblingBMaxMiddle
                    + " maxEnd=" + siblingAMaxEnd + "/" + siblingBMaxEnd);
        }

        TimePeriodValues inv = null;
        int invCount = 0;
        int invIdx = -1;
        double chosenMid = Double.NaN;
        double maxMid = Double.NaN;
        try {
            inv = new TimePeriodValues("S");
            int n = data.consumeInt(1, 5);
            for (int i = 0; i < n; i++) {
                long a = data.consumeInt(-1000000, 1000000);
                long b = data.consumeInt(-1000000, 1000000);
                long start = Math.min(a, b);
                long end = Math.max(a, b);
                inv.add(new SimpleTimePeriod(start, end), data.consumeInt(-1000000, 1000000));
            }
            invCount = inv.getItemCount();
            invIdx = inv.getMaxMiddleIndex();
            if (invIdx >= 0 && invIdx < invCount) {
                chosenMid = middle(inv.getTimePeriod(invIdx));
                maxMid = -Double.MAX_VALUE;
                for (int i = 0; i < invCount; i++) {
                    double mid = middle(inv.getTimePeriod(i));
                    if (mid > maxMid) {
                        maxMid = mid;
                    }
                }
            }
        } catch (Throwable t) {
            return;
        }

        /* Contract justification: getMaxMiddleIndex() is documented to return the index of the time period with the maximum middle milliseconds.
           A patch that merely suppresses an error or points to a different cached field breaks this observable post-condition without throwing. */
        if (invIdx < 0 || invIdx >= invCount || chosenMid != maxMid) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:max-middle-maximum] relation max_middle_index_points_to_a_maximum_middle violated: idx="
                    + invIdx + " count=" + invCount + " chosenMid=" + chosenMid + " maxMid=" + maxMid);
        }

        TimePeriodValues equalDuration = null;
        int midIdx = -1;
        int endIdx = -1;
        try {
            equalDuration = new TimePeriodValues("S");
            int n = data.consumeInt(1, 5);
            long d = data.consumeInt(0, 1000);
            for (int i = 0; i < n; i++) {
                long start = data.consumeInt(-1000000, 1000000);
                long end = start + d;
                equalDuration.add(new SimpleTimePeriod(start, end), data.consumeInt(-1000000, 1000000));
            }
            midIdx = equalDuration.getMaxMiddleIndex();
            endIdx = equalDuration.getMaxEndIndex();
        } catch (Throwable t) {
            return;
        }

        /* Contract justification: when all periods have the same duration, middle = end - constant, so the index of the maximum middle
           must equal the index of the maximum end for every correct implementation. */
        if (midIdx != endIdx) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:equal-duration] relation equal_duration_max_middle_matches_max_end violated: midIdx="
                    + midIdx + " endIdx=" + endIdx);
        }
    }
}

