package org.apache.commons.math.analysis.solvers;

import com.code_intelligence.jazzer.api.FuzzedDataProvider;

public class FuzzHarness {
    public static void fuzzerTestOneInput(FuzzedDataProvider data) {
        org.apache.commons.math.analysis.SinFunction f = new org.apache.commons.math.analysis.SinFunction();

        checkLiftedBadInterval2Arg(f);
        checkLiftedNonBracketing2Arg(f);
        checkLiftedNonBracketing4Arg(f);

        checkMirroredNegativeNonBracketingSeed(f);
        checkBoundaryFlipSymmetry(data, f);
        checkReuseAfterRejectedNegativeSameSign(data, f);
    }

    private static void checkLiftedBadInterval2Arg(org.apache.commons.math.analysis.SinFunction f) {
        boolean completedNormally = false;
        try {
            UnivariateRealSolver solver = new BrentSolver();
            solver.solve(f, 1.0, -1.0);
            completedNormally = true;
        } catch (IllegalArgumentException expected) {
            return;
        } catch (Throwable t) {
            return;
        }
        if (completedNormally) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-bad-interval-2arg] semantic mismatch: BrentSolver.solve(f, 1, -1) completed normally; BrentSolverTest.testBadEndpoints expects IllegalArgumentException for bad interval");
        }
    }

    private static void checkLiftedNonBracketing2Arg(org.apache.commons.math.analysis.SinFunction f) {
        boolean completedNormally = false;
        try {
            UnivariateRealSolver solver = new BrentSolver();
            solver.solve(f, 1.0, 1.5);
            completedNormally = true;
        } catch (IllegalArgumentException expected) {
            return;
        } catch (Throwable t) {
            return;
        }
        if (completedNormally) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-nonbracketing-2arg] semantic mismatch: BrentSolver.solve(f, 1, 1.5) completed normally; BrentSolverTest.testBadEndpoints expects IllegalArgumentException for non-bracketing");
        }
    }

    private static void checkLiftedNonBracketing4Arg(org.apache.commons.math.analysis.SinFunction f) {
        boolean completedNormally = false;
        try {
            UnivariateRealSolver solver = new BrentSolver();
            solver.solve(f, 1.0, 1.5, 1.2);
            completedNormally = true;
        } catch (IllegalArgumentException expected) {
            return;
        } catch (Throwable t) {
            return;
        }
        if (completedNormally) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:lifted-nonbracketing-4arg] semantic mismatch: BrentSolver.solve(f, 1, 1.5, 1.2) completed normally; BrentSolverTest.testBadEndpoints expects IllegalArgumentException for non-bracketing");
        }
    }

    private static void checkMirroredNegativeNonBracketingSeed(org.apache.commons.math.analysis.SinFunction f) {
        boolean completedNormally = false;
        try {
            UnivariateRealSolver solver = new BrentSolver();
            solver.solve(f, -1.5, -1.0, -1.2);
            completedNormally = true;
        } catch (IllegalArgumentException expected) {
            return;
        } catch (Throwable t) {
            return;
        }
        if (completedNormally) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:mirrored-negative-nonbracketing-4arg] semantic mismatch: BrentSolver.solve(f, -1.5, -1.0, -1.2) completed normally even though sin(min), sin(initial), and sin(max) all have the same negative sign, so the documented four-arg solve rejection applies just as in the positive seed");
        }
    }

    private static void checkBoundaryFlipSymmetry(FuzzedDataProvider data, org.apache.commons.math.analysis.SinFunction f) {
        double base = data.consumeInt(100, 1300) / 1000.0;
        double width = data.consumeInt(50, 200) / 1000.0;
        double minPos = base;
        double maxPos = base + width;
        double initialPos = minPos + (maxPos - minPos) / 2.0;

        double minNeg = -maxPos;
        double maxNeg = -minPos;
        double initialNeg = -initialPos;

        Boolean posRejected = null;
        try {
            new BrentSolver().solve(f, minPos, maxPos, initialPos);
            posRejected = Boolean.FALSE;
        } catch (IllegalArgumentException expected) {
            posRejected = Boolean.TRUE;
        } catch (Throwable t) {
            return;
        }

        Boolean negRejected = null;
        try {
            new BrentSolver().solve(f, minNeg, maxNeg, initialNeg);
            negRejected = Boolean.FALSE;
        } catch (IllegalArgumentException expected) {
            negRejected = Boolean.TRUE;
        } catch (Throwable t) {
            return;
        }

        if (posRejected.booleanValue() != negRejected.booleanValue()) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:sign-polarity-symmetry] metamorphic violation: mirrored same-sign intervals on SinFunction must be rejected identically by solve(f,min,max,initial); positiveInterval=[" +
                minPos + "," + maxPos + "," + initialPos + "] rejected=" + posRejected +
                " negativeInterval=[" + minNeg + "," + maxNeg + "," + initialNeg + "] rejected=" + negRejected);
        }
    }

    private static void checkReuseAfterRejectedNegativeSameSign(FuzzedDataProvider data, org.apache.commons.math.analysis.SinFunction f) {
        double exponent = data.consumeInt(4, 10);
        double accuracy = Math.pow(10.0, -exponent);

        BrentSolver reused = new BrentSolver();
        BrentSolver fresh = new BrentSolver();
        reused.setAbsoluteAccuracy(accuracy);
        fresh.setAbsoluteAccuracy(accuracy);

        try {
            reused.solve(f, -1.5, -1.0, -1.2);
            return;
        } catch (IllegalArgumentException expected) {
        } catch (Throwable t) {
            return;
        }

        double reusedResult;
        double freshResult;
        try {
            reusedResult = reused.solve(f, -1.0, 1.0);
            freshResult = fresh.solve(f, -1.0, 1.0);
        } catch (Throwable t) {
            return;
        }

        double tol = Math.max(accuracy * 4.0, 1.0e-12);

        if (Math.abs(reusedResult - freshResult) > tol) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:rejected-call-does-not-poison-later-solve] consistency violation: after a documented rejection, a BrentSolver should remain equivalent to a fresh BrentSolver with the same configuration on the next successful solve; reusedResult=" +
                reusedResult + " freshResult=" + freshResult + " accuracy=" + accuracy);
        }

        double reusedReported = reused.getResult();
        double freshReported = fresh.getResult();
        if (Math.abs(reusedReported - reusedResult) > tol || Math.abs(freshReported - freshResult) > tol) {
            throw new com.code_intelligence.jazzer.api.FuzzerSecurityIssueLow(
                "[oracle:post-solve-reported-result-consistency] consistency violation: getResult() must report the same root value the preceding successful solve established; reusedResult=" +
                reusedResult + " reusedReported=" + reusedReported + " freshResult=" + freshResult + " freshReported=" + freshReported + " accuracy=" + accuracy);
        }
    }
}

